using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Drawing;using System.Windows.Forms;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {
static class LoginStore {
static string Location(bool remote){string qa=Environment.GetEnvironmentVariable("OREUMMOK_DATA_DIR");string dir=!String.IsNullOrEmpty(qa)&&qa.Contains("qa-native")?Path.Combine(qa,"login-preferences"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OreumMokLogin");Directory.CreateDirectory(dir);return Path.Combine(dir,remote?"client.json":"admin.json");}
public static D Load(bool remote){try{string p=Location(remote);return File.Exists(p)?J.Obj(J.S.DeserializeObject(File.ReadAllText(p,Encoding.UTF8))):new D();}catch{return new D();}}
static void Write(bool remote,D values){string file=Location(remote),tmp=file+".tmp";File.WriteAllText(tmp,J.S.Serialize(values),new UTF8Encoding(false));if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);}
public static string Token(bool remote){try{D data=Load(remote);if(!J.Bool(data,"auto"))return "";byte[] encrypted=Convert.FromBase64String(J.Text(data,"protectedToken"));return Encoding.UTF8.GetString(ProtectedData.Unprotect(encrypted,Encoding.UTF8.GetBytes("OreumMok-Login-v1"),DataProtectionScope.CurrentUser));}catch{return "";}}
public static void Save(bool remote,string host,string username,bool rememberId,bool automatic,string token){D value=J.Row("rememberId",rememberId||automatic,"auto",automatic,"username",rememberId||automatic?username:"","host",host,"protectedToken","");if(automatic){if(String.IsNullOrEmpty(token))throw new Exception("자동 로그인 정보를 받지 못했습니다.");value["protectedToken"]=Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(token),Encoding.UTF8.GetBytes("OreumMok-Login-v1"),DataProtectionScope.CurrentUser));}Write(remote,value);}
public static void Forget(bool remote,bool keepId=true){D data=Load(remote);data["auto"]=false;data["protectedToken"]="";if(!keepId){data["username"]="";data["rememberId"]=false;}Write(remote,data);}
}
class Login:Form {public D User;Bridge bridge;bool remote,setup;D saved;TextBox host=new TextBox(),username=new TextBox(),password=new TextBox(),confirm=new TextBox(),name=new TextBox();CheckBox remember=new CheckBox(),automatic=new CheckBox();Label message=new Label();public Login(Bridge b,bool forceRemote=false){bridge=b;remote=forceRemote||b.IsRemote;saved=LoginStore.Load(remote);Style.Form(this);Text=remote?"오름목 배포 사용자 · 로그인":"오름목 관리자 PC · 로그인";Width=560;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;setup=!remote&&!J.Bool(bridge.Call("status"),"initialized");Height=Math.Min(setup?810:remote?740:660,Screen.PrimaryScreen.WorkingArea.Height-30);var panel=new TableLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(32),ColumnCount=1};Controls.Add(panel);string image=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"app-icon.png");if(File.Exists(image))panel.Controls.Add(new PictureBox{Image=Image.FromFile(image),SizeMode=PictureBoxSizeMode.Zoom,Height=78,Dock=DockStyle.Top});panel.Controls.Add(new Label{Text="오름목  OREUM MOK",Font=new Font(Font.FontFamily,23,FontStyle.Bold),AutoSize=true});panel.Controls.Add(new Label{Text=setup?"처음 사용할 관리자 계정을 만드세요.":remote?"관리자 PC에 연결 · 허용된 업무만 사용":"관리자 PC 프로그램 · 계정 권한에 맞춰 로그인",AutoSize=true});if(remote){host.Text=J.Text(saved,"host","https://oreummok-cloud.onrender.com");Add(panel,"관리자 PC 주소 (http://주소:48733)",host);}username.Text=J.Bool(saved,"rememberId")?J.Text(saved,"username"):"";Add(panel,"아이디 (영문·숫자 3~32자)",username);if(setup)Add(panel,"이름",name);password.UseSystemPasswordChar=true;Add(panel,"비밀번호",password);if(setup){confirm.UseSystemPasswordChar=true;Add(panel,"비밀번호 확인",confirm);}remember.Text="아이디 저장";automatic.Text="자동 로그인 (이 기기 · 최대 30일)";remember.AutoSize=automatic.AutoSize=true;remember.Checked=J.Bool(saved,"rememberId");automatic.Checked=J.Bool(saved,"auto");panel.Controls.Add(remember);panel.Controls.Add(automatic);remember.CheckedChanged+=(o,e)=>{if(!remember.Checked){automatic.Checked=false;try{LoginStore.Forget(remote,false);}catch{}}};automatic.CheckedChanged+=(o,e)=>{if(automatic.Checked)remember.Checked=true;else try{LoginStore.Forget(remote,remember.Checked);}catch{}};panel.Controls.Add(new Label{Text="비밀번호는 저장하지 않습니다. 자동 로그인은 개인 기기에서 선택하세요.",AutoSize=true,ForeColor=Style.Muted});message.AutoSize=true;message.ForeColor=Color.Firebrick;panel.Controls.Add(message);var button=Style.Button(setup?"관리자 등록 및 로그인":"로그인",Submit);button.Dock=DockStyle.Top;panel.Controls.Add(button);AcceptButton=button;if(!setup&&automatic.Checked)Shown+=(o,e)=>BeginInvoke(new Action(TryAuto));}
void Add(TableLayoutPanel p,string label,TextBox field){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(0,12,0,5)});field.Dock=DockStyle.Top;p.Controls.Add(field);}
void PrepareHost(){if(!remote)return;Uri u;if(!Uri.TryCreate(host.Text.Trim().TrimEnd('/'),UriKind.Absolute,out u)||!((u.Scheme=="https"&&u.Port==443)||(u.Scheme=="http"&&u.Port==48733))||u.AbsolutePath!="/"||u.UserInfo!=""||u.Query!=""||u.Fragment!="")throw new Exception("관리자 PC 주소를 http://주소:48733 형식으로 입력하세요.");bridge.RemoteUrl=u.GetLeftPart(UriPartial.Authority);}
void TryAuto(){string token=LoginStore.Token(remote);if(token=="")return;try{PrepareHost();D result=bridge.Call("resume",J.Row("token",token));User=J.Obj(result["user"]);DialogResult=DialogResult.OK;Close();}catch(Exception ex){message.Text="자동 로그인에 연결하지 못했습니다. 직접 로그인할 수 있습니다.\n"+ex.Message;if(ex.Message.Contains("만료")||ex.Message.Contains("권한")){automatic.Checked=false;LoginStore.Forget(remote,true);}}}
void Submit(object sender,EventArgs e){try{PrepareHost();if(setup){if(password.Text!=confirm.Text)throw new Exception("비밀번호 확인이 다릅니다.");bridge.Call("setup",J.Row("username",username.Text.Trim(),"name",name.Text,"password",password.Text));setup=false;}D result=bridge.Call("login",J.Row("username",username.Text.Trim(),"password",password.Text,"remember",automatic.Checked));User=J.Obj(result["user"]);LoginStore.Save(remote,remote?bridge.RemoteUrl:"local",username.Text.Trim(),remember.Checked,automatic.Checked,J.Text(result,"deviceToken"));password.Clear();confirm.Clear();DialogResult=DialogResult.OK;Close();}catch(Exception ex){message.Text=ex.Message;}}
}
class RemoteLogin:Login {public RemoteLogin(Bridge bridge):base(bridge,true){}}
}
